//! Drawing the book (P7b) in its local space through `paint::Painter`.
//!
//! The atlas `mistbrn:gui/progress` is generated by `tools/gen-progress.py` (Claude ⇄ Codex);
//! its regions are the contract below. The reserve gems come from `mistbrn:gui/hud`.
use super::{
    Book, CANVAS, CONCLUDE_BUTTON, DETAIL_W, DETAIL_X, HINT_BUTTON, LIST, LIST_ROW, PANEL_H,
    PANEL_W, TABS, Tab, Target, frame, hint_page_rect, inside, map, max_list_scroll, tab_key,
    target_at, targets, unlocking_milestone,
};
use crate::hud::{tr, tr_args};
use crate::paint::Painter;
use allomancy_core::{
    BASE_FLARE_MILLI, BurnState, CATALOG, HudSnapshot, Metal, NodeDef, NodeEffect, NodeStatus,
    Pair, Pool, Progress, Requirement, node_def, node_status, research_def, research_ready,
    xp_to_next_point,
};
use mod_api::{ClientHost, DrawContext};

const SHEET: &str = "mistbrn:gui/progress";
const SHEET_SIZE: [f32; 2] = [128.0, 80.0];
const HUD_SHEET: &str = "mistbrn:gui/hud";
const HUD_SIZE: [f32; 2] = [160.0, 64.0];
const NODE_LOCKED: [f32; 4] = [0.0, 0.0, 22.0, 22.0];
const NODE_AVAILABLE: [f32; 4] = [22.0, 0.0, 22.0, 22.0];
const NODE_OWNED: [f32; 4] = [44.0, 0.0, 22.0, 22.0];
const NODE_HOVER: [f32; 4] = [66.0, 0.0, 22.0, 22.0];
const ICON_Y: f32 = 24.0;
const ICON_Y_P8: f32 = 64.0;
const ICON_RESEARCH: [f32; 4] = [80.0, 24.0, 16.0, 16.0];
const ICON_HINT: [f32; 4] = [96.0, 24.0, 16.0, 16.0];
const PIP_EMPTY: [f32; 4] = [112.0, 24.0, 4.0, 4.0];
const PIP_FULL: [f32; 4] = [116.0, 24.0, 4.0, 4.0];
const TAB: [f32; 4] = [0.0, 40.0, 48.0, 14.0];
const TAB_SELECTED: [f32; 4] = [48.0, 40.0, 48.0, 14.0];
const CHECK_FOUND: [f32; 4] = [96.0, 40.0, 9.0, 9.0];
const CHECK_MISSING: [f32; 4] = [105.0, 40.0, 9.0, 9.0];
const POINT: [f32; 4] = [114.0, 40.0, 7.0, 7.0];

const BODY: u32 = 0xE018_1A20;
const OUTLINE: u32 = 0xFF0A_0B0E;
const BEVEL: u32 = 0xFF45_4A50;
const TEXT: u32 = 0xFFE0_E0E0;
const DIM: u32 = 0xFF90_9090;
const BRASS: u32 = 0xFFF0_D48A;
const READY: u32 = 0xFFB8_E0A0;
/// The Conclude refusal note: warm and lighter than the body text's grey.
const REFUSED: u32 = 0xFFF0_A070;
const LOCKED_TINT: u32 = 0xFF70_7070;
const LOCKED_ICON_TINT: u32 = 0xFF9C_9C9C;
/// A silhouette: the locked frame, darker, with no icon.
const HIDDEN_TINT: u32 = 0xFF48_4A4E;
/// A locked pair's sector: darker still, nothing on it.
const SECTOR_TINT: u32 = 0xFF34_3639;
const BUTTON: u32 = 0xFF2E_3238;
const BUTTON_HOVER: u32 = 0xFF45_4A50;
const LINK: u32 = 0xFF3A_3E44;
const LINK_LIT: u32 = 0xFFB0_9050;
const WELL: u32 = 0xFF10_1114;
const SCROLL_THUMB: u32 = 0xFF6A_6E74;
const LINE: f32 = 10.0;

/// How the book looks this frame: the settings and the clock for the one pulse it has.
#[derive(Clone, Copy, Debug)]
pub(crate) struct Look {
    pub(crate) scale: f32,
    /// `reduce_flashes`: nothing pulses.
    pub(crate) steady: bool,
    pub(crate) ticks: u64,
}

fn sprite(p: &mut Painter, src: [f32; 4], at: [f32; 2], tint: Option<u32>) -> bool {
    p.sprite(SHEET, SHEET_SIZE, src, [at[0], at[1], src[2], src[3]], tint)
}

fn button(p: &mut Painter, rect: [f32; 4], hovered: bool) {
    p.fill(rect, OUTLINE);
    let fill = if hovered { BUTTON_HOVER } else { BUTTON };
    p.fill(
        [rect[0] + 1.0, rect[1] + 1.0, rect[2] - 2.0, rect[3] - 2.0],
        fill,
    );
}

/// The keyboard focus: a brass outline around `rect`.
fn focus_ring(p: &mut Painter, [x, y, w, h]: [f32; 4]) {
    p.fill([x - 1.0, y - 1.0, w + 2.0, 1.0], BRASS);
    p.fill([x - 1.0, y + h, w + 2.0, 1.0], BRASS);
    p.fill([x - 1.0, y, 1.0, h], BRASS);
    p.fill([x + w, y, 1.0, h], BRASS);
}

/// A node's icon in the sheet: a cell per catalog node, in catalog order. The first row holds
/// five before the research and hint icons; the next ones (P8) start a row at `ICON_Y_P8`.
fn icon(code: u16) -> Option<[f32; 4]> {
    let index = CATALOG.nodes.iter().position(|def| def.code == code)?;
    let (column, y) = if index < 5 {
        (index, ICON_Y)
    } else {
        (index - 5, ICON_Y_P8)
    };
    (column < 8).then_some([16.0 * column as f32, y, 16.0, 16.0])
}

/// The value an effect shows to a player: blocks or percent.
fn shown_value(effect: NodeEffect, value: u16) -> String {
    match effect {
        NodeEffect::ReductionMilli | NodeEffect::CapacityBonusMilli | NodeEffect::DosingMilli => {
            tenths(u32::from(value))
        }
        // The flare multiplier left: 300 → «2.7».
        NodeEffect::FlareCostMilli => {
            let left = BASE_FLARE_MILLI as u32 - u32::from(value).min(2_000);
            format!("{}.{}", left / 1_000, left % 1_000 / 100)
        }
        _ => value.to_string(),
    }
}

/// `value` tenths as text: 125 → «12.5», 100 → «10».
fn tenths(value: u32) -> String {
    match value % 10 {
        0 => format!("{}", value / 10),
        t => format!("{}.{t}", value / 10),
    }
}

fn node_name(host: &dyn ClientHost, def: &NodeDef) -> String {
    tr(host, &format!("node.mistbrn.{}", def.key))
}

fn pair_label(host: &dyn ClientHost, pair: Pair) -> String {
    tr(
        host,
        &format!("hud.mistbrn.pair.{}", crate::controls::pair_name(pair)),
    )
}

fn wrap(p: &Painter, text: &str, width: f32) -> Vec<String> {
    let mut lines = Vec::new();
    let mut line = String::new();
    for word in text.split_whitespace() {
        let candidate = if line.is_empty() {
            word.to_string()
        } else {
            format!("{line} {word}")
        };
        if !line.is_empty() && p.text_width(&candidate) > width {
            lines.push(std::mem::replace(&mut line, word.to_string()));
        } else {
            line = candidate;
        }
    }
    if !line.is_empty() {
        lines.push(line);
    }
    lines
}

/// `text` cut with «…» to fit `width`.
fn fit(p: &Painter, text: &str, width: f32) -> String {
    if p.text_width(text) <= width {
        return text.to_string();
    }
    let mut cut: String = text.to_string();
    while !cut.is_empty() && p.text_width(&format!("{cut}…")) > width {
        cut.pop();
    }
    format!("{cut}…")
}

/// A points count, right-aligned at `at`, with its gem before it.
fn draw_points(p: &mut Painter, at: [f32; 2], text: &str) {
    let x = at[0] - p.text_width(text);
    p.text(text, [x, at[1]], TEXT, true);
    if !sprite(p, POINT, [x - POINT[2] - 2.0, at[1]], None) {
        p.fill([x - 7.0, at[1] + 1.0, 5.0, 5.0], BRASS);
    }
}

/// Draws the book over the world. `unlocked` answers whether a pair is unlocked (from the HUD
/// snapshot); `progress` is `None` until the server's first snapshot arrives. Keeps the
/// frame's place and scale in `book` for the clicks of the next frame.
#[allow(clippy::too_many_arguments)]
pub(crate) fn draw(
    host: &dyn ClientHost,
    draw: &mut dyn DrawContext,
    book: &mut Book,
    progress: Option<&Progress>,
    hud: Option<&HudSnapshot>,
    unlocked: &dyn Fn(Pair) -> bool,
    pointer: [f32; 2],
    look: Look,
) {
    let size = draw.size();
    // The places of a locked sector are silhouettes: `targets` reads this (`PAIRS` order).
    book.unlocked = allomancy_core::PAIRS.map(unlocked);
    draw.fill([0.0, 0.0, size[0], size[1]], 0x6000_0000);
    let (origin, scale) = frame(size, look.scale);
    book.frame = Some((origin, scale));
    let local = book.local(pointer).unwrap_or([-1.0, -1.0]);
    let mut p = Painter::new(draw, origin, scale);
    for tab in TABS {
        let rect = super::tab_rect(tab);
        let src = if tab == book.tab { TAB_SELECTED } else { TAB };
        // Three slices: the 4-px ends as drawn, the middle stretched to the tab's width.
        let [sx, sy, sw, sh] = src;
        let [x, y, w, _] = rect;
        let ends = sprite(&mut p, [sx, sy, 4.0, sh], [x, y], None)
            && sprite(&mut p, [sx + sw - 4.0, sy, 4.0, sh], [x + w - 4.0, y], None);
        if ends {
            p.sprite(
                SHEET,
                SHEET_SIZE,
                [sx + 4.0, sy, sw - 8.0, sh],
                [x + 4.0, y, w - 8.0, sh],
                None,
            );
        } else {
            p.fill(rect, if tab == book.tab { BEVEL } else { BUTTON });
        }
        let label = tr(host, &format!("notebook.mistbrn.tab.{}", tab_key(tab)));
        let color = if tab == book.tab { BRASS } else { DIM };
        let label = fit(&p, &label, rect[2] - 4.0);
        let x = rect[0] + (rect[2] - p.text_width(&label)) / 2.0;
        p.text(&label, [x, rect[1] + 3.0], color, true);
    }
    p.fill([0.0, 0.0, PANEL_W, PANEL_H], OUTLINE);
    p.fill([1.0, 1.0, PANEL_W - 2.0, PANEL_H - 2.0], BEVEL);
    p.fill([2.0, 2.0, PANEL_W - 4.0, PANEL_H - 4.0], BODY);
    let Some(progress) = progress else {
        let wait = tr(host, "notebook.mistbrn.waiting");
        p.text(&wait, [8.0, 8.0], DIM, true);
        return;
    };
    let hovered = target_at(book, progress, local);
    match book.tab {
        Tab::Tree => draw_map(host, &mut p, book, progress, unlocked, hovered, look),
        Tab::Diary => draw_diary(host, &mut p, book, progress, hovered),
        Tab::Milestones => draw_milestones(host, &mut p, progress),
        Tab::Reserves => draw_reserves(host, &mut p, progress, hud),
    }
    // The focus ring, over whatever it is on (the canvas's nodes only while they show).
    let focused = book.focus.and_then(|f| {
        targets(book, progress)
            .into_iter()
            .find(|(t, _, shown)| *t == f && *shown)
    });
    if let Some((_, rect, _)) = focused {
        focus_ring(&mut p, rect);
    }
    // The tooltip: what the pointer is over, else what has the focus. Right after a keyboard
    // move the focus wins until the pointer moves (Codex review, round 2).
    if book.last_pointer != Some(pointer) {
        book.last_pointer = Some(pointer);
        book.keyboard = false;
    }
    let hovered_tip = hovered.filter(|_| !book.keyboard);
    let tip = match (hovered_tip, focused) {
        (Some(target), _) => Some((target, local)),
        (None, Some((target, rect, _))) => Some((target, [rect[0] + rect[2], rect[1]])),
        (None, None) => None,
    };
    if let Some((target, at)) = tip {
        let lines = tooltip(host, target, progress, unlocked);
        if !lines.is_empty() {
            p.tooltip(&lines, at);
        }
    }
}

/// The tooltip lines of `target` (none for tabs and plain buttons).
fn tooltip(
    host: &dyn ClientHost,
    target: Target,
    progress: &Progress,
    unlocked: &dyn Fn(Pair) -> bool,
) -> Vec<String> {
    match target {
        Target::Node(code) => {
            let Some(def) = node_def(code, &CATALOG) else {
                return Vec::new();
            };
            let owned = progress.rank(code);
            let status = node_status(progress, def, unlocked, &CATALOG);
            let mut lines = vec![format!(
                "{} {}/{}",
                node_name(host, def),
                owned,
                def.ranks.len()
            )];
            match def.ranks.get(usize::from(owned)) {
                None => lines.push(tr(host, "notebook.mistbrn.status.owned")),
                Some(rank) => {
                    lines.push(tr_args(
                        host,
                        &format!("node.mistbrn.{}.effect", def.key),
                        &[shown_value(def.effect, rank.value)],
                    ));
                    lines.push(tr_args(
                        host,
                        "notebook.mistbrn.cost",
                        &[rank.cost.to_string()],
                    ));
                }
            }
            let note = match status {
                NodeStatus::Available => tr(host, "notebook.mistbrn.status.available"),
                NodeStatus::TooExpensive => tr(host, "notebook.mistbrn.status.expensive"),
                NodeStatus::Owned => String::new(),
                NodeStatus::Locked => requirement_text(host, def, progress, unlocked),
            };
            if !note.is_empty() {
                lines.push(note);
            }
            lines
        }
        Target::Innate(metal) => vec![
            tr(
                host,
                &format!("node.mistbrn.innate.{}", crate::bridge::metal_name(metal)),
            ),
            tr(host, "notebook.mistbrn.innate"),
        ],
        Target::Locked(pair) => {
            let mut lines = vec![pair_label(host, pair)];
            if let Some(m) = unlocking_milestone(pair) {
                lines.push(tr_args(
                    host,
                    "notebook.mistbrn.pair.locked",
                    &[tr(host, &format!("milestone.mistbrn.{}", m.key))],
                ));
                lines.push(tr(host, &format!("milestone.mistbrn.{}.where", m.key)));
            }
            lines
        }
        Target::Hidden => vec![
            tr(host, "notebook.mistbrn.hidden"),
            tr(host, "notebook.mistbrn.hidden.later"),
        ],
        // None for Conclude: the pointer stays on the button after a click and a tooltip there
        // covered the note above it, which already says where to stand (p7b-final2 l3-refused).
        _ => Vec::new(),
    }
}

fn requirement_text(
    host: &dyn ClientHost,
    def: &NodeDef,
    progress: &Progress,
    unlocked: &dyn Fn(Pair) -> bool,
) -> String {
    if let Pool::Pair(pair) = def.pool
        && !unlocked(pair)
    {
        return tr(host, "notebook.mistbrn.requires.pair");
    }
    for requirement in def.requires {
        match *requirement {
            Requirement::Node { code, rank } if progress.rank(code) < rank => {
                let name =
                    node_def(code, &CATALOG).map_or_else(String::new, |d| node_name(host, d));
                return tr_args(
                    host,
                    "notebook.mistbrn.requires.node",
                    &[name, rank.to_string()],
                );
            }
            Requirement::Discovery { code } if !progress.discovered(code) => {
                let name = research_def(code, &CATALOG).map_or_else(String::new, |d| {
                    tr(host, &format!("research.mistbrn.{}", d.key))
                });
                return tr_args(host, "notebook.mistbrn.requires.discovery", &[name]);
            }
            _ => {}
        }
    }
    String::new()
}

/// The pair whose sector the view is in (`None`: the centre).
fn sector_in_view(book: &Book) -> Option<Pair> {
    let [x, y] = book.view.pan;
    if x.hypot(y) < 80.0 {
        return None;
    }
    let angle = y.atan2(x).to_degrees();
    map::SECTOR_ORDER.into_iter().min_by(|a, b| {
        let off = |pair| {
            let d = (angle - map::bisector(pair)).rem_euclid(360.0);
            d.min(360.0 - d)
        };
        off(*a).total_cmp(&off(*b))
    })
}

/// The map tab (P8): a header for the sector in view, then the map through a clip.
fn draw_map(
    host: &dyn ClientHost,
    p: &mut Painter,
    book: &Book,
    progress: &Progress,
    unlocked: &dyn Fn(Pair) -> bool,
    hovered: Option<Target>,
    look: Look,
) {
    let x = CANVAS[0];
    let right = CANVAS[0] + CANVAS[2];
    let (title, line) = match sector_in_view(book) {
        Some(pair) => {
            let line = if !unlocked(pair) {
                let how = unlocking_milestone(pair).map_or_else(String::new, |m| {
                    tr(host, &format!("milestone.mistbrn.{}", m.key))
                });
                tr_args(host, "notebook.mistbrn.pair.locked", &[how])
            } else {
                let points = progress.available(Pool::Pair(pair), &CATALOG).to_string();
                draw_points(p, [right, 4.0], &points);
                let xp = progress.pair_xp(pair);
                tr_args(
                    host,
                    "notebook.mistbrn.xp",
                    &[xp.to_string(), xp_to_next_point(xp, &CATALOG).to_string()],
                )
            };
            (pair_label(host, pair), line)
        }
        None => {
            let points = progress.available(Pool::Knowledge, &CATALOG).to_string();
            draw_points(p, [right, 4.0], &points);
            (
                tr(host, "notebook.mistbrn.general"),
                tr(host, "notebook.mistbrn.general.help"),
            )
        }
    };
    p.text(&title, [x, 4.0], BRASS, true);
    let line = fit(p, &line, CANVAS[2]);
    p.text(&line, [x, 14.0], DIM, true);

    p.fill(CANVAS, WELL);
    p.push_clip(CANVAS);
    let view = book.view;
    let (_, links) = map::map_layout();
    let lit = |target: Target| match target {
        Target::Node(code) => progress.rank(code) > 0,
        Target::Innate(metal) => unlocked(metal.pair()),
        _ => false,
    };
    // Links first, under the nodes: dotted, a 2-pixel dot every 3 pixels.
    for (from, to, into) in links {
        let color = if lit(into) { LINK_LIT } else { LINK };
        let [ax, ay] = view.to_local(from);
        let [bx, by] = view.to_local(to);
        let steps = ((bx - ax).hypot(by - ay) / 3.0).ceil().max(1.0) as usize;
        for i in 0..=steps {
            let t = i as f32 / steps as f32;
            let (dx, dy) = (ax + (bx - ax) * t, ay + (by - ay) * t);
            if inside([dx, dy], CANVAS) {
                p.fill([dx - 1.0, dy - 1.0, 2.0, 2.0], color);
            }
        }
    }
    // A locked sector's name and the milestone that opens it, over its silhouette.
    for pair in map::SECTOR_ORDER {
        if unlocked(pair) {
            continue;
        }
        let [cx, cy] = view.to_local(map::polar(map::LABEL_R, map::bisector(pair)));
        let name = pair_label(host, pair);
        p.text(
            &name,
            [cx - p.text_width(&name) / 2.0, cy - 10.0],
            DIM,
            true,
        );
        if let Some(m) = unlocking_milestone(pair) {
            let how = tr(host, &format!("milestone.mistbrn.{}", m.key));
            p.text(&how, [cx - p.text_width(&how) / 2.0, cy + 1.0], DIM, true);
        }
    }
    // The pulse of a node that can be bought: a soft brightening every 1.5 s, none when
    // `reduce_flashes` is on.
    let pulse = if look.steady {
        0.0
    } else {
        let phase = (look.ticks % 30) as f32 / 30.0 * std::f32::consts::TAU;
        (phase.sin() + 1.0) / 2.0
    };
    for (target, rect, _) in targets(book, progress) {
        if !matches!(target, Target::Tab(_)) && overlaps(rect, CANVAS) {
            draw_place(p, target, rect, progress, unlocked, hovered, pulse);
        }
    }
    p.pop_clip();
}

fn overlaps(a: [f32; 4], b: [f32; 4]) -> bool {
    a[0] < b[0] + b[2] && b[0] < a[0] + a[2] && a[1] < b[1] + b[3] && b[1] < a[1] + a[3]
}

/// A sprite of the progress sheet drawn `k` times its size at `at`.
fn sprite_at(p: &mut Painter, src: [f32; 4], at: [f32; 2], k: f32, tint: Option<u32>) -> bool {
    p.sprite(
        SHEET,
        SHEET_SIZE,
        src,
        [at[0], at[1], src[2] * k, src[3] * k],
        tint,
    )
}

/// One place of the map in the local `rect` (a node's square at the view's zoom).
fn draw_place(
    p: &mut Painter,
    target: Target,
    rect: [f32; 4],
    progress: &Progress,
    unlocked: &dyn Fn(Pair) -> bool,
    hovered: Option<Target>,
    pulse: f32,
) {
    let at = [rect[0], rect[1]];
    let k = rect[2] / 22.0;
    let is_hovered =
        hovered == Some(target) && matches!(target, Target::Node(_) | Target::Innate(_));
    match target {
        Target::Node(code) => {
            let Some(def) = node_def(code, &CATALOG) else {
                return;
            };
            let status = node_status(progress, def, unlocked, &CATALOG);
            let frame = if is_hovered {
                NODE_HOVER
            } else {
                match status {
                    NodeStatus::Locked | NodeStatus::TooExpensive => NODE_LOCKED,
                    NodeStatus::Available => NODE_AVAILABLE,
                    NodeStatus::Owned => NODE_OWNED,
                }
            };
            if !sprite_at(p, frame, at, k, None) {
                p.fill(rect, BEVEL);
            }
            if status == NodeStatus::Available && pulse > 0.0 {
                let alpha = (pulse * 64.0) as u32;
                p.fill(
                    [at[0] + 2.0 * k, at[1] + 2.0 * k, 18.0 * k, 18.0 * k],
                    alpha << 24 | 0x00F0_D48A,
                );
            }
            // Lighter than the locked frame, so the icon still reads (Codex, round 1).
            let tint = (status == NodeStatus::Locked).then_some(LOCKED_ICON_TINT);
            if let Some(src) = icon(code) {
                sprite_at(p, src, [at[0] + 3.0 * k, at[1] + 3.0 * k], k, tint);
            }
            let owned = usize::from(progress.rank(code));
            let pips = def.ranks.len() as f32;
            let start = at[0] + 11.0 * k - (pips * 6.0 - 2.0) / 2.0;
            for i in 0..def.ranks.len() {
                let src = if i < owned { PIP_FULL } else { PIP_EMPTY };
                sprite(
                    p,
                    src,
                    [start + 6.0 * i as f32, at[1] + rect[3] + 2.0],
                    None,
                );
            }
        }
        Target::Innate(metal) => {
            let open = unlocked(metal.pair());
            let frame = match (is_hovered, open) {
                (true, _) => NODE_HOVER,
                (false, true) => NODE_OWNED,
                (false, false) => NODE_LOCKED,
            };
            if !sprite_at(p, frame, at, k, None) {
                p.fill(rect, BEVEL);
            }
            // The metal's gem, from the HUD sheet.
            let gem = [8.0 * metal.index() as f32, 56.0, 8.0, 8.0];
            let side = 12.0 * k;
            let dst = [
                at[0] + (rect[2] - side) / 2.0,
                at[1] + (rect[3] - side) / 2.0,
                side,
                side,
            ];
            p.sprite(
                HUD_SHEET,
                HUD_SIZE,
                gem,
                dst,
                (!open).then_some(LOCKED_TINT),
            );
        }
        Target::Locked(_) => {
            if !sprite_at(p, NODE_LOCKED, at, k, Some(SECTOR_TINT)) {
                p.fill(rect, LINK);
            }
        }
        _ => {
            if !sprite_at(p, NODE_LOCKED, at, k, Some(HIDDEN_TINT)) {
                p.fill(rect, LINK);
            }
            if k >= 0.75 {
                p.text(
                    "?",
                    [at[0] + rect[2] / 2.0 - 2.0, at[1] + rect[3] / 2.0 - 4.0],
                    0xFF6A_6E74,
                    false,
                );
            }
        }
    }
}

/// A thin bar at the right edge of `window` while it can scroll.
fn scroll_bar(p: &mut Painter, window: [f32; 4], value: f32, max: f32) {
    if max <= 0.0 {
        return;
    }
    let [x, y, w, h] = window;
    let thumb = (h * h / (h + max)).max(12.0);
    let top = y + (h - thumb) * (value / max);
    p.fill([x + w - 3.0, y, 3.0, h], OUTLINE);
    p.fill([x + w - 3.0, top, 3.0, thumb], SCROLL_THUMB);
}

/// One row per milestone: a check and the name (brass once claimed), what it gives on the
/// right, then where to look in up to two lines; each row is as tall as its text.
fn draw_milestones(host: &dyn ClientHost, p: &mut Painter, progress: &Progress) {
    let mut y = 8.0;
    for def in CATALOG.milestones {
        let claimed = progress.claimed(def.bit);
        let check = if claimed { CHECK_FOUND } else { CHECK_MISSING };
        sprite(p, check, [8.0, y], None);
        let name = tr(host, &format!("milestone.mistbrn.{}", def.key));
        let color = if claimed { BRASS } else { TEXT };
        p.text(&name, [22.0, y + 1.0], color, true);
        let reward = match def.unlocks {
            Some(pair) => tr_args(
                host,
                "notebook.mistbrn.milestone.unlocks",
                &[pair_label(host, pair)],
            ),
            None => tr_args(
                host,
                "notebook.mistbrn.milestone.knowledge",
                &[def.knowledge.to_string()],
            ),
        };
        let x = PANEL_W - 8.0 - p.text_width(&reward);
        p.text(&reward, [x, y + 1.0], color, true);
        let hint = tr(host, &format!("milestone.mistbrn.{}.where", def.key));
        let lines = wrap(p, &hint, PANEL_W - 30.0);
        let shown = lines.len().min(2);
        for (i, line) in lines.iter().take(shown).enumerate() {
            p.text(line, [22.0, y + 12.0 + LINE * i as f32], DIM, true);
        }
        y += 18.0 + LINE * shown as f32;
    }
}

/// The diary: the list of research on the left, the chosen one on the right.
fn draw_diary(
    host: &dyn ClientHost,
    p: &mut Painter,
    book: &Book,
    progress: &Progress,
    hovered: Option<Target>,
) {
    p.fill(LIST, WELL);
    p.push_clip(LIST);
    for (i, def) in CATALOG.research.iter().enumerate() {
        let y = LIST[1] + LIST_ROW * i as f32 - book.list_scroll;
        let rect = [LIST[0], y, LIST[2], LIST_ROW - 2.0];
        let chosen = def.code == book.research;
        if chosen || hovered == Some(Target::Research(def.code)) {
            p.fill(rect, BUTTON_HOVER);
        }
        sprite(p, ICON_RESEARCH, [rect[0] + 2.0, y + 6.0], None);
        let entry = progress.research(def.code);
        let color = if entry.concluded {
            BRASS
        } else if research_ready(progress, def) {
            READY
        } else {
            TEXT
        };
        let name = tr(host, &format!("research.mistbrn.{}", def.key));
        let lines = wrap(p, &name, LIST[2] - 26.0);
        let top = if lines.len() > 1 { y + 4.0 } else { y + 9.0 };
        for (n, line) in lines.iter().take(2).enumerate() {
            let line = fit(p, line, LIST[2] - 26.0);
            p.text(&line, [rect[0] + 21.0, top + LINE * n as f32], color, true);
        }
    }
    p.pop_clip();
    scroll_bar(p, LIST, book.list_scroll, max_list_scroll());

    let Some(def) = research_def(book.research, &CATALOG) else {
        return;
    };
    let x = DETAIL_X;
    let right = DETAIL_X + DETAIL_W;
    let entry = progress.research(def.code);
    let (status, color) = if entry.concluded {
        ("notebook.mistbrn.research.discovered", BRASS)
    } else if research_ready(progress, def) {
        ("notebook.mistbrn.research.ready", READY)
    } else {
        ("notebook.mistbrn.research.open", DIM)
    };
    let status = tr(host, status);
    p.text(&status, [right - p.text_width(&status), 8.0], color, true);
    let name = fit(
        p,
        &tr(host, &format!("research.mistbrn.{}", def.key)),
        right - x - p.text_width(&status) - 6.0,
    );
    p.text(&name, [x, 8.0], BRASS, true);
    let found = entry.evidence.count_ones().min(u32::from(def.needed));
    let count = tr_args(
        host,
        "notebook.mistbrn.evidence",
        &[found.to_string(), def.needed.to_string()],
    );
    p.text(&count, [x, 24.0], TEXT, true);
    // Each piece of evidence: what was seen, or a blank until it is (discovery stays free).
    let mut y = 36.0;
    for bit in [1u8, 2, 4] {
        if def.evidence & bit == 0 {
            continue;
        }
        let seen = entry.evidence & bit != 0;
        let check = if seen { CHECK_FOUND } else { CHECK_MISSING };
        sprite(p, check, [x, y], None);
        let text = if seen {
            tr(
                host,
                &format!("research.mistbrn.{}.evidence.{bit}", def.key),
            )
        } else {
            tr(host, "notebook.mistbrn.evidence.unknown")
        };
        let text = fit(p, &text, DETAIL_W - 14.0);
        p.text(
            &text,
            [x + 13.0, y + 1.0],
            if seen { TEXT } else { DIM },
            true,
        );
        y += 12.0;
    }

    sprite(p, ICON_HINT, [x - 2.0, 82.0], None);
    p.text(
        &tr(host, "notebook.mistbrn.hints"),
        [x + 18.0, 86.0],
        BRASS,
        true,
    );
    if entry.hints < def.hints {
        button(p, HINT_BUTTON, hovered == Some(Target::RevealHint));
        let label = tr_args(
            host,
            "notebook.mistbrn.reveal",
            &[(entry.hints + 1).to_string(), def.hints.to_string()],
        );
        let lx = HINT_BUTTON[0] + (HINT_BUTTON[2] - p.text_width(&label)) / 2.0;
        p.text(&label, [lx, HINT_BUTTON[1] + 2.0], TEXT, true);
    }
    let ready = !entry.concluded && research_ready(progress, def);
    let bottom = if ready {
        CONCLUDE_BUTTON[1] - 24.0
    } else {
        PANEL_H - 12.0
    };
    let mut y = 102.0;
    if entry.hints == 0 {
        for line in wrap(p, &tr(host, "notebook.mistbrn.hints.none"), DETAIL_W) {
            p.text(&line, [x, y], DIM, true);
            y += LINE;
        }
    }
    // One hint at a time (the newest unless another page is chosen): long hints never push
    // a just-revealed one out of the panel.
    let page = book
        .hint_page
        .unwrap_or(entry.hints)
        .clamp(1, entry.hints.max(1));
    for index in 1..=entry.hints {
        let rect = hint_page_rect(index);
        let shown = page == index;
        button(p, rect, shown || hovered == Some(Target::HintPage(index)));
        let label = index.to_string();
        let lx = rect[0] + (12.0 - p.text_width(&label)) / 2.0;
        p.text(
            &label,
            [lx, rect[1] + 2.0],
            if shown { BRASS } else { TEXT },
            true,
        );
    }
    if entry.hints > 0 {
        let hint = tr(host, &format!("research.mistbrn.{}.hint.{page}", def.key));
        for line in wrap(p, &hint, DETAIL_W) {
            if y + LINE > bottom {
                break;
            }
            p.text(&line, [x, y], TEXT, true);
            y += LINE;
        }
    }
    if ready {
        let (key, color) = if book.refused {
            ("notebook.mistbrn.conclude.refused", REFUSED)
        } else {
            ("notebook.mistbrn.research.how", READY)
        };
        // Up to two lines above the button (the hints stop above them).
        let lines = wrap(p, &tr(host, key), DETAIL_W);
        let shown = lines.len().min(2);
        for (i, line) in lines.iter().take(shown).enumerate() {
            let y = CONCLUDE_BUTTON[1] - 11.0 - LINE * (shown - 1 - i) as f32;
            // The last shown line says so when more text did not fit.
            let more = i + 1 == shown && lines.len() > shown;
            let line = if more {
                format!("{line} …")
            } else {
                line.clone()
            };
            p.text(&fit(p, &line, DETAIL_W), [x, y], color, true);
        }
        button(p, CONCLUDE_BUTTON, hovered == Some(Target::Conclude));
        let label = tr(host, "notebook.mistbrn.conclude");
        let lx = CONCLUDE_BUTTON[0] + (CONCLUDE_BUTTON[2] - p.text_width(&label)) / 2.0;
        p.text(&label, [lx, CONCLUDE_BUTTON[1] + 3.0], READY, true);
    }
}

/// The reserves: one row per metal (gem, name, bar, reserve / capacity, state), then the
/// general tree's effects.
fn draw_reserves(
    host: &dyn ClientHost,
    p: &mut Painter,
    progress: &Progress,
    hud: Option<&HudSnapshot>,
) {
    const BAR: [f32; 2] = [84.0, 100.0];
    let Some(hud) = hud else {
        p.text(&tr(host, "notebook.mistbrn.waiting"), [8.0, 8.0], DIM, true);
        return;
    };
    for (i, metal) in Metal::ALL.into_iter().enumerate() {
        let entry = hud.metals[metal.index()];
        let y = 8.0 + 20.0 * i as f32;
        let gem = [8.0 * metal.index() as f32, 24.0, 6.0, 6.0];
        let tint = (!entry.unlocked).then_some(LOCKED_TINT);
        p.sprite(HUD_SHEET, HUD_SIZE, gem, [10.0, y + 4.0, 6.0, 6.0], tint);
        let name = tr(
            host,
            &format!("hud.mistbrn.metal.{}", crate::bridge::metal_name(metal)),
        );
        let color = if entry.unlocked { TEXT } else { DIM };
        let name = fit(p, &name, BAR[0] - 24.0);
        p.text(&name, [20.0, y + 3.0], color, true);
        p.fill([BAR[0], y + 4.0, BAR[1], 6.0], OUTLINE);
        let (state, fill) = match (entry.unlocked, entry.burn) {
            (false, _) => ("locked", DIM),
            (true, BurnState::Off) => ("off", 0xFF80_8080),
            (true, BurnState::Burning) => ("burning", 0xFFC8_A050),
            (true, BurnState::Flared) => ("flared", 0xFFFF_7030),
        };
        if entry.unlocked && entry.capacity_milli > 0 {
            let share = (entry.reserve_milli as f32 / entry.capacity_milli as f32).clamp(0.0, 1.0);
            p.fill([BAR[0] + 1.0, y + 5.0, (BAR[1] - 2.0) * share, 4.0], fill);
            let amount = format!(
                "{} / {}",
                tenths(entry.reserve_milli / 100),
                tenths(entry.capacity_milli / 100)
            );
            p.text(&amount, [BAR[0] + BAR[1] + 6.0, y + 3.0], TEXT, true);
        }
        let state = tr(host, &format!("notebook.mistbrn.reserve.{state}"));
        let sx = PANEL_W - 8.0 - p.text_width(&state);
        p.text(&state, [sx, y + 3.0], color, true);
    }
    let rank_value = |code: u16| {
        node_def(code, &CATALOG)
            .and_then(|def| {
                let rank = usize::from(progress.rank(code));
                rank.checked_sub(1).and_then(|r| def.ranks.get(r))
            })
            .map_or(0, |rank| u32::from(rank.value))
    };
    let effects = tr_args(
        host,
        "notebook.mistbrn.reserve.effects",
        &[
            tenths(rank_value(allomancy_core::NODE_ECONOMY)),
            tenths(rank_value(allomancy_core::NODE_CAPACITY)),
        ],
    );
    let effects = fit(p, &effects, PANEL_W - 16.0);
    p.text(&effects, [8.0, PANEL_H - 16.0], DIM, true);
}
